\begin{theorem}\label{thm:main}
Every compact, connected Riemannian isometric filling \(M\) of a circle of length \(2\pi\), orientable or not, satisfies
\begin{equation}\label{eq 1.2}
\operatorname{Area}(M)\ge \frac{14\zeta(3)}{\pi}
\approx 5.35677,
\end{equation}
where \(\zeta\) denotes the Riemann zeta function.    
\end{theorem}

\begin{theorem}\label{thm:main orientable}
Every compact, connected orientable Riemannian isometric filling \(M\) of a circle of length \(2\pi\) satisfies
\[
\operatorname{Area}(M)>5.40154.
\]   
\end{theorem}

\begin{lemma}\label{lemma 2.2}
For every fixed $\theta\in\T$,
$$|\nabla u_\theta(x)|=1$$
at every point $x\in M^\circ$ at which $u_\theta$ is differentiable. Consequently, this identity holds for almost every $(x,\theta)\in M^\circ\times\T$.
\end{lemma}

\begin{lemma}\label{lem:boundary-fourier}
For every positive odd integer $n$,
$$z_n(\gamma(s))=-\rho_ne^{ins},$$
where $\rho_n:=\frac4{\pi n^2}$. 
\end{lemma}

\begin{proposition}\label{prop 2.5}
Let $m_1,\ldots,m_N$ be distinct positive odd integers, and let $U=(u_{jk})\in O(N)$. Define
$$G_j:=\sum_{k=1}^N u_{jk}F_{m_k},\qquad 1\leq j\leq N.$$
Then
\begin{equation}\label{eq:jacobian-bound}
\sum_{j=1}^N J_2G_j(x)\leq1
\end{equation}
for almost every $x\in M^\circ$. 
Here $J_2G_j$ denotes the two-dimensional
Jacobian.
\end{proposition}

\begin{lemma}\label{lemma 3.2}
Every row of $U_N$ satisfies
$$|u_{j1}|>\sum_{k=2}^N\frac{|u_{jk}|}{m_k},\qquad 1\leq j\leq N.$$
\end{lemma}

\begin{lemma}\label{lemma 3.4}
Let $M$ be a compact connected surface with exactly one boundary component, and let $G:M\to\R^2$ be continuous. Suppose that $G|_{\partial M}$ is an embedding, and let $\Omega$ be the bounded component of $\R^2\setminus G(\partial M)$. Then
$$\Omega\subset G(M).$$
If $M$ is Riemannian and $G$ is Lipschitz, then
$$ \int_MJ_2G\,dA\geq|\Omega|. $$
\end{lemma}

\begin{proposition}\label{prop:finite-universal-bound}
Let $M$ be a compact connected Riemannian isometric filling of the circle of length $2\pi$. Then, for every $N\geq1$,
$$\operatorname{Area}(M) \geq \frac{16}{\pi}\sum_{k=1}^N\frac1{(2k-1)^3}.$$
\end{proposition}

\begin{theorem}\label{thm:nonlinear-formula}
Let $M$ be a compact connected orientable Riemannian isometric filling of $\T$. For every $0\leq\lambda<\pi^2/32$, we have
\begin{equation}\label{eq:nonlinear-master}
\operatorname{Area}(M)\geq
\frac{C_0+b\lambda+d\lambda^2}
{1+\lambda^2\left[
Q_*+\dfrac{C_*^2}{4(1-D_*\lambda)}
\right]}.
\end{equation}
In particular,
$$\operatorname{Area}(M)>5.40154.$$
\end{theorem}

\begin{proposition}\label{prop:nonlinear-boundary-action}
For every $\lambda\geq0$, we have
\begin{equation}\label{eq:nonlinear-boundary-action}
\int_M\Omega_\lambda
=B(\lambda)
:=\pi\sum_{n\in\mathcal O}
n\left(\rho_n+\lambda\rho_1^2\rho_{n+2}\right)^2
=C_0+b\lambda+d\lambda^2.
\end{equation}
In particular, $b>0$.
\end{proposition}

\begin{lemma}\label{lem:nonlinear-first-variation}
Writing $a=z_1$ and $y_n=z_{n+2}$, we have
\begin{equation}\label{eq:nonlinear-first-variation}
\begin{aligned}
L={}&2\operatorname{Re}\left[a^2\sum_{n\in\mathcal O}\left(\overline{c_n}c_{n+2}-c_{-n}\overline{c_{-(n+2)}}\right)\right]\\
&+4\operatorname{Re}\left[a\sum_{n\in\mathcal O}\overline{y_n}
\left(c_{-1}\overline{c_n}-\overline{c_1}c_{-n}\right)\right].
\end{aligned}
\end{equation}
In particular, $L=0$ whenever $|\Omega_0|=1$.
\end{lemma}

\begin{proposition}\label{prop:nonlinear-linear-estimate}
At every common differentiability point and for every ordered orthonormal basis, set
$$\delta=1-|\Omega_0|.$$
Then
\begin{equation}\label{eq:nonlinear-linear-estimate}
|L|\leq C_*\sqrt\delta+D_*\delta.
\end{equation}
\end{proposition}

\begin{lemma}\label{lem:nonlinear-quadratic-estimate}
At every common differentiability point and for every ordered orthonormal basis, we have
$$ |Q|\leq Q_*.$$
\end{lemma}
